function completedOutput(history,node){
  const workflowId=node.graph?.id;
  for(const [id,record] of Object.entries(history).sort((a,b)=>(b[1].prompt?.[0]||0)-(a[1].prompt?.[0]||0))){
    const graph=record.prompt?.[2],workflow=record.prompt?.[3]?.extra_pnginfo?.workflow;
    if(!record.status?.completed||record.status.status_str!=='success'||graph?.[node.id]?.class_type!==TYPE||workflowId&&workflow?.id!==workflowId)continue;
    // Expanded internal nodes are persisted under descendant IDs rather than
    // the displayed parent ID. Match only this workflow's H3 node subtree.
    const own=Object.entries(record.outputs||{}).filter(([id])=>id===String(node.id)||id.startsWith(`${node.id}.`));
    const native=own.find(([,o])=>o.h3fs_files?.length)?.[1]||record.outputs?.[node.id]||own.find(([,o])=>o.text)?.[1];
    let text=(native?.h3fs_final_prompt||native?.text)?.join('\n');const files=[...(native?.h3fs_files||[])];
    for(const [outputId,outputNode] of Object.entries(graph)){
      const output=record.outputs?.[outputId];
      if(outputNode.inputs?.text?.[0]===String(node.id)&&outputNode.inputs.text[1]===2&&output?.text)text=output.text.join('\n');
      const input=outputNode.inputs?.video;
      if(input?.[0]!==String(node.id)||![0,1].includes(input[1]))continue;
      const file=output?.images?.find(f=>/\.mp4$/i.test(f.filename));
      if(file)files[input[1]]={name:input[1]?'Upscaled':'Original',url:'/view?'+new URLSearchParams({filename:file.filename,subfolder:file.subfolder||'',type:file.type||'output'})};
    }
    return {id,text,original:graph[node.id].inputs.prompt,optimized:JSON.parse(graph[node.id].inputs.settings||'{}').optimize_on_run,files:files.filter(Boolean)};
  }
}
