api.addEventListener('kj_preview_override',e=>panelFor(e.detail.node_id)?.previewEvent(e.detail));api.addEventListener('h3fs_status',e=>{const p=panelFor(e.detail.node_id);if(p){const sampling=/ · \d+×\d+ · /.test(e.detail.text);if(e.detail.text==='Optimizing intent'||sampling)p.startPreview();if(p.state.global_reference?.enabled&&(sampling||e.detail.text==='Optimizing intent'))p.globalProgress({stage:sampling?'video':'video_prompt',text:sampling?'正在生成视频 · '+e.detail.text:'正在根据实际素材设计视频提示词…',done:0,total:sampling?p.state.steps:1});p.status(e.detail.text);}});
api.addEventListener('h3fs_prompt',e=>panelFor(e.detail.node_id)?.setPrompt(e.detail.text,e.detail));
api.addEventListener('h3fs_prompt_candidate',e=>panelFor(e.detail.node_id)?.setPromptCandidate(e.detail));
api.addEventListener('h3fs_postprocess',e=>{const p=panelFor(e.detail.node_id);if(p){p.status(e.detail.text);p.globalProgress(e.detail);}});
api.addEventListener('h3fs_partial_result',e=>{const p=panelFor(e.detail.node_id);if(p){p.renderResults(e.detail.files);p.status(e.detail.text);p.save();}});
api.addEventListener('execution_error',e=>{const p=panelFor(e.detail.node_id);if(p){const text='任务中断：'+(e.detail.exception_message||'请查看后端日志')+' 已完成的素材和提示词已保留，可检查后继续。';p.status(text,true);p.globalProgress({stage:'error',text});}});
api.addEventListener('h3fs_optimizer_error',e=>panelFor(e.detail.node_id)?.status(e.detail.text,true));api.addEventListener('h3fs_result',e=>{const p=panelFor(e.detail.node_id);if(p){p.renderResults(e.detail.files);p.globalProgress({stage:'complete_video',text:'完整视频已保存，可以预览',done:1,total:1});p.status('完整视频已保存，可以预览');p.save();}});
api.addEventListener('execution_success',()=>{historyRequest=null;for(const [node,p]of panels)if(node.graph===app.graph)p.restoreHistory();});
api.addEventListener('h3fs_reference_progress',e=>panelFor(e.detail.node_id)?.referenceProgress(e.detail));
api.addEventListener('h3fs_reference_result',e=>panelFor(e.detail.node_id)?.referenceResult(e.detail.job));
